// ── Aggregate Daily Metrics ───────────────────────────────
// Items come from Merge (append mode): MESSAGE_LEDGER rows + ERRORS rows.
// Separate by field presence.

const today = new Date().toISOString().slice(0, 10);

let ledgerRows = [];
let errorRows = [];

for (const item of items) {
  const d = item.json;
  if (d.message_id) ledgerRows.push(d);
  else if (d.error_message) errorRows.push(d);
}

// Filter for today's data
const todayLedger = ledgerRows.filter(r => (r.processed_at || '').slice(0, 10) === today);
const todayErrors = errorRows.filter(r => (r.timestamp || '').slice(0, 10) === today);

const totalMessages  = todayLedger.length;
const processedCount = todayLedger.filter(r => r.status === 'processed' || r.status === 'replied').length;
const cachedCount    = todayLedger.filter(r => r.status === 'cached' || r.status === 'delivery_update').length;
const driftCount     = todayLedger.filter(r => (r.status || '').includes('drift')).length;
const cancelCount    = todayLedger.filter(r => r.status === 'cancelled').length;
const bookingCount   = todayLedger.filter(r => r.status === 'booking_done').length;

const errorCount     = todayErrors.length;
const errorTypes     = [...new Set(todayErrors.map(r => r.error_type))];
const environment    = ledgerRows[0]?.environment || errorRows[0]?.environment || 'unknown';

return [{
  json: {
    date:                 today,
    total_messages:       totalMessages,
    processed:            processedCount,
    cached_duplicates:    cachedCount,
    cancellations:        cancelCount,
    bookings_completed:   bookingCount,
    drift_events:         driftCount,
    errors_total:         errorCount,
    distinct_error_types: errorTypes.join(', '),
    environment:          environment,
    computed_at:          new Date().toISOString()
  }
}];
